/// The values every page shares: the sidebar, the top bar and the flash message.
#[derive(Debug, Clone, Serialize)]
pub(crate) struct Layout {
    pub(crate) home_url: String,
    pub(crate) signed_in: bool,
    pub(crate) user_name: String,
    pub(crate) user_initials: String,
    pub(crate) has_avatar: bool,
    pub(crate) avatar_url: String,
    pub(crate) theme: String,
    pub(crate) theme_url: String,
    /// Whether the page shows the light and dark switch ([`AdminTheme::theme_switcher`](crate::AdminTheme::theme_switcher)).
    pub(crate) theme_switcher: bool,
    pub(crate) profile_url: String,
    pub(crate) logout_everywhere_url: String,
    pub(crate) csrf_token: String,
    /// Every entry of the sidebar, in the order shown, without the group headings, each child
    /// entry after its parent. The `ignite` theme reads `nav_sections`; `nav` stays for themes
    /// that list the entries as before.
    pub(crate) nav: Vec<NavGroup>,
    /// The sidebar in sections: the entries without a navigation group first, without a
    /// heading, then one section per group, under its heading.
    pub(crate) nav_sections: Vec<NavSection>,
    /// Whether a section of the sidebar is collapsible, so the navigation needs its script.
    pub(crate) nav_collapsible: bool,
    pub(crate) has_flash: bool,
    pub(crate) flash: String,
    /// The CSS of the active admin theme's colour tokens, or empty when it has none. The
    /// layout prints it raw: the tokens are checked when the theme is registered.
    pub(crate) theme_style: String,
    /// The admin theme the page renders in.
    pub(crate) admin_theme: AdminThemeView,
    /// The panel's brand: its name, logo and favicon (see [`Ignite::brand_name`](crate::Ignite::brand_name)).
    pub(crate) brand: BrandView,
}

/// One entry of the sidebar: a list, and a link to add a record when the resource has forms.
///
/// An entry with a create link or child entries is a group, as a WordPress menu with its
/// submenu: its `sub_items` (the create link, then each child entry followed by its own create
/// link) show only while the group is open, and the toggle beside the entry opens and closes
/// it. A group is open when the entry or one of its children is the current page.
#[derive(Debug, Clone, Serialize)]
pub(crate) struct NavGroup {
    pub(crate) title: String,
    /// The CSS classes of the entry's icon, as the admin theme resolves its name.
    pub(crate) icon: String,
    /// The icon's name, such as `post` (`NAVIGATION_ICON`), or empty when the resource names
    /// none.
    pub(crate) icon_name: String,
    pub(crate) url: String,
    /// Whether the entry has a create link: the resource lists one (`NAVIGATION_CREATE_ITEM`)
    /// and the user may create a record.
    pub(crate) has_add: bool,
    pub(crate) add_url: String,
    /// The create link's label (`NAVIGATION_CREATE_LABEL`), such as "Add new".
    pub(crate) add_label: String,
    pub(crate) active: bool,
    /// The links of the entry's group, in order: its create link, then each child entry and
    /// that child's create link.
    pub(crate) sub_items: Vec<NavLink>,
    pub(crate) has_sub_items: bool,
    /// Whether the group shows its `sub_items`: the entry or one of its children is the current
    /// page. `closed` is the opposite, and `aria_expanded` is `"true"` or `"false"`, for the
    /// toggle.
    pub(crate) open: bool,
    pub(crate) closed: bool,
    pub(crate) aria_expanded: &'static str,
    /// The `id` of the element that holds `sub_items`, for the toggle's `aria-controls`.
    pub(crate) sub_items_id: String,
    /// The entries listed under this one (Filament's child items), in order. A child has none.
    pub(crate) children: Vec<NavGroup>,
    pub(crate) has_children: bool,
    /// Whether one of the children is the current page. The entry itself is then not active.
    pub(crate) has_active_child: bool,
    /// Whether the children show: the entry or one of its children is the current page, as
    /// Filament shows an item's children.
    pub(crate) expanded: bool,
}

impl NavGroup {
    /// The entry of `node` with the entries listed under it, or `None` for a label-only
    /// parent without children. A label-only parent (the node's flag) links to its first
    /// child, as a Filament cluster's navigation item opens the cluster's first page.
    fn from_node(node: Node<(NavGroup, bool)>) -> Option<NavGroup> {
        let (mut item, label_only) = node.item;
        let children: Vec<NavGroup> = node.children.into_iter().map(|(child, _)| child).collect();
        if label_only {
            item.url = children.first()?.url.clone();
        }
        Some(NavGroup::with_children(Node { item, children }))
    }

    /// The entry `item` with the entries listed under it.
    fn with_children(node: Node<NavGroup>) -> NavGroup {
        let has_active_child = node.children.iter().any(|child| child.active);
        let mut sub_items = Vec::new();
        if node.item.has_add {
            sub_items.push(NavLink::create_link(&node.item));
        }
        for child in &node.children {
            sub_items.push(NavLink {
                title: child.title.clone(),
                url: child.url.clone(),
                active: child.active,
            });
            if child.has_add {
                sub_items.push(NavLink::create_link(child));
            }
        }
        let open = !sub_items.is_empty() && (node.item.active || has_active_child);
        NavGroup {
            has_children: !node.children.is_empty(),
            expanded: !node.children.is_empty() && (node.item.active || has_active_child),
            has_active_child,
            children: node.children,
            has_sub_items: !sub_items.is_empty(),
            sub_items,
            open,
            closed: !open,
            aria_expanded: if open { "true" } else { "false" },
            ..node.item
        }
    }
}

/// One link of a navigation entry's group: a child entry, or a create link.
#[derive(Debug, Clone, Serialize)]
pub(crate) struct NavLink {
    pub(crate) title: String,
    pub(crate) url: String,
    /// Whether the link is the current page.
    pub(crate) active: bool,
}

impl NavLink {
    /// The create link of `entry`.
    fn create_link(entry: &NavGroup) -> NavLink {
        NavLink {
            title: entry.add_label.clone(),
            url: entry.add_url.clone(),
            active: false,
        }
    }
}

/// A section of the sidebar: a navigation group's entries under its heading, or the entries
/// without a group, which have no heading (`has_heading` false).
#[derive(Debug, Clone, Serialize)]
pub(crate) struct NavSection {
    pub(crate) has_heading: bool,
    pub(crate) heading: String,
    pub(crate) items: Vec<NavGroup>,
    /// Whether the heading collapses and expands the entries, as Filament's collapsible
    /// navigation groups. Only a section with a heading is collapsible.
    pub(crate) collapsible: bool,
    /// Whether the group starts collapsed (`NavigationGroup::collapsed`) until the user
    /// expands it. The page renders every group expanded; the navigation's script collapses
    /// it, so without JavaScript every group shows its entries.
    pub(crate) collapsed: bool,
    /// Whether an entry of the section, or a child of one, is the current page. The script
    /// keeps such a group expanded.
    pub(crate) active: bool,
    /// The `id` of the element that holds the entries, for the heading's `aria-controls`.
    pub(crate) items_id: String,
}

/// The initials of a name, for the avatar: "Ada Lovelace" gives "AL".
fn initials(name: &str) -> String {
    name.split_whitespace()
        .filter_map(|word| word.chars().next())
        .take(2)
        .flat_map(char::to_uppercase)
        .collect()
}

impl Layout {
    /// The layout for a page. `section` is the slug of the page's resource, or empty for
    /// the dashboard, and marks its entry in the sidebar. Signed-out pages have neither
    /// the sidebar nor the top bar.
    pub(crate) fn new(
        registry: &Registry,
        user: Option<&AdminUser>,
        section: &str,
        flash: Option<String>,
        csrf_token: String,
    ) -> Self {
        // The menu's icons, the colour tokens and the stylesheets come from the admin theme of
        // the request: the signed-in user's choice, or the site default.
        // The signed-in user's admin theme, or the site default.
        let admin_theme = crate::theme::resolve(user.and_then(AdminUser::admin_theme_choice));
        // A resource is listed only when the user may view its records, and its "Add new"
        // link only when the user may create one, as Filament's navigation does. The entries
        // are placed by their navigation group, sort and parent item (see `crate::navigation`).
        let nav_sections: Vec<NavSection> = match user {
            Some(user) => {
                // The dashboard is the first entry, before every group, as Filament's is: it
                // has no sort, and the ungrouped entries keep the order they were added in.
                // A resource may list itself under it.
                // Each entry carries whether it is a label-only parent the panel declared
                // (`Ignite::navigation_items` without a URL): it takes its first child's URL.
                let entry_view = |title: &str, icon: Option<&str>, url: String| NavGroup {
                    title: title.to_string(),
                    icon: icon_classes(admin_theme.theme.as_ref(), icon),
                    icon_name: icon.unwrap_or_default().to_string(),
                    url,
                    has_add: false,
                    add_url: String::new(),
                    add_label: String::new(),
                    active: false,
                    sub_items: Vec::new(),
                    has_sub_items: false,
                    open: false,
                    closed: true,
                    aria_expanded: "false",
                    sub_items_id: String::new(),
                    children: Vec::new(),
                    has_children: false,
                    has_active_child: false,
                    expanded: false,
                };
                let dashboard = Entry {
                    key: String::new(),
                    label: "Dashboard".to_string(),
                    group: None,
                    sort: None,
                    parent: None,
                    item: (
                        NavGroup {
                            active: section.is_empty(),
                            ..entry_view(
                                "Dashboard",
                                Some(icons::DASHBOARD),
                                registry.mount.clone(),
                            )
                        },
                        false,
                    ),
                };
                let items = registry
                    .navigation_items
                    .iter()
                    .filter(|item| item.ability_name().is_none_or(|ability| user.can(ability)))
                    .map(|item| Entry {
                        // A declared entry is found by its label; its key is never a slug.
                        key: format!("\u{0}{}", item.label()),
                        label: item.label().to_string(),
                        group: item.group_name().map(str::to_string),
                        sort: item.sort_value(),
                        parent: None,
                        item: (
                            entry_view(
                                item.label(),
                                item.icon_name(),
                                item.url_value().unwrap_or_default().to_string(),
                            ),
                            item.url_value().is_none(),
                        ),
                    });
                let entries = std::iter::once(dashboard)
                    .chain(items)
                    .chain(
                        registry
                            .all()
                            .into_iter()
                            .filter(|r| user.may(r.slug(), Action::ViewAny))
                            .map(|r| Entry {
                                key: r.slug().to_string(),
                                label: r.navigation_label().to_string(),
                                group: r.navigation_group().map(str::to_string),
                                sort: r.navigation_sort(),
                                parent: r.navigation_parent_item().map(str::to_string),
                                item: (
                                    NavGroup {
                                        has_add: r.navigation_create_item().is_some()
                                            && user.may(r.slug(), Action::Create),
                                        add_url: format!("{}/{}/new", registry.mount, r.slug()),
                                        add_label: r
                                            .navigation_create_item()
                                            .unwrap_or_default()
                                            .to_string(),
                                        active: section == r.slug(),
                                        ..entry_view(
                                            r.navigation_label(),
                                            r.navigation_icon(),
                                            format!("{}/{}", registry.mount, r.slug()),
                                        )
                                    },
                                    false,
                                ),
                            }),
                    )
                    .collect();
                let declared: Vec<String> = registry
                    .navigation_groups
                    .iter()
                    .map(|group| group.label().to_string())
                    .collect();
                arrange(entries, &declared)
                    .into_iter()
                    .enumerate()
                    .map(|(index, section)| {
                        let items: Vec<NavGroup> = section
                            .items
                            .into_iter()
                            .filter_map(NavGroup::from_node)
                            .enumerate()
                            .map(|(item, group)| NavGroup {
                                sub_items_id: format!("ig-nav-items-{index}-{item}"),
                                ..group
                            })
                            .collect();
                        // A group the panel does not declare follows the panel's default. A
                        // group declared twice takes the options of its last declaration.
                        let declared = section.heading.as_deref().and_then(|heading| {
                            registry
                                .navigation_groups
                                .iter()
                                .rev()
                                .find(|group| group.label() == heading)
                        });
                        let default = registry.collapsible_navigation_groups;
                        let collapsible = section.heading.is_some()
                            && declared.map_or(default, |group| group.is_collapsible(default));
                        NavSection {
                            has_heading: section.heading.is_some(),
                            heading: section.heading.unwrap_or_default(),
                            collapsible,
                            collapsed: collapsible
                                && declared.is_some_and(|group| group.is_collapsed(default)),
                            active: items
                                .iter()
                                .any(|item| item.active || item.has_active_child),
                            items_id: format!("ig-nav-group-{index}"),
                            items,
                        }
                    })
                    .collect()
            }
            None => Vec::new(),
        };
        let nav = nav_sections
            .iter()
            .flat_map(|section| &section.items)
            .flat_map(|item| std::iter::once(item).chain(&item.children))
            .cloned()
            .collect();
        let nav_collapsible = nav_sections.iter().any(|section| section.collapsible);
        Layout {
            home_url: registry.mount.clone(),
            signed_in: user.is_some(),
            user_name: user.map(|u| u.name().to_string()).unwrap_or_default(),
            user_initials: user.map(|u| initials(u.name())).unwrap_or_default(),
            has_avatar: user.is_some_and(|u| u.has_avatar() || u.avatar_url().is_some()),
            // The app's picture of the user wins over an uploaded one. A timestamp in the URL of
            // an uploaded picture makes the browser fetch it again after a change.
            avatar_url: match user.and_then(AdminUser::avatar_url) {
                Some(url) => url.to_string(),
                None => format!(
                    "{}/profile/avatar?v={}",
                    registry.mount,
                    chrono::Utc::now().timestamp_millis()
                ),
            },
            // A theme without a dark mode renders light, whatever the user chose elsewhere.
            theme: user
                .filter(|_| admin_theme.theme.dark_mode())
                .map(|u| u.theme().to_string())
                .unwrap_or_else(|| "light".to_string()),
            theme_url: format!("{}/theme", registry.mount),
            theme_switcher: admin_theme.theme.theme_switcher(),
            profile_url: format!("{}/profile", registry.mount),
            logout_everywhere_url: format!("{}/logout-everywhere", registry.mount),
            nav,
            nav_sections,
            nav_collapsible,
            csrf_token,
            has_flash: flash.is_some(),
            flash: flash.unwrap_or_default(),
            theme_style: admin_theme.style.clone(),
            admin_theme: AdminThemeView {
                name: admin_theme.theme.name().to_string(),
                stylesheets: admin_theme.theme.stylesheets(),
            },
            brand: BrandView::new(&registry.brand),
        }
    }
}

/// The dashboard: a row of stat cards.
